export function blockDistance(x1: i32, y1: i32, z1: i32, x2: i32, y2: i32, z2: i32): f64 {
  const dx = <f64>(x2 - x1);
  const dy = <f64>(y2 - y1);
  const dz = <f64>(z2 - z1);
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

export function posOffset(pos: Int32Array, dx: i32, dy: i32, dz: i32): void {
  pos[0] += dx;
  pos[1] += dy;
  pos[2] += dz;
}

